var numTrue = function(state) {
  var fun = function(x) {
    x ? 1 : 0
  }
  return sum(map(fun,state))
}

// possible utterances
var utterances = ["null","every-not"];
var utterancePrior = function() {
  uniformDraw(utterances)
}
// uniform utterance cost
